// Auto-generated exact triangulated mesh from reference/SC_MM_Inlay.step
// Generated from load_blank_inlay_base() with BRepMesh
// Contains 476 triangles (1428 vertices) encoded as base64 Float32Array.

const INLAY_BASE_B64 = "";

let cachedGeometry: Float32Array | null = null;

export function getInlayBasePositions(): Float32Array {
  if (cachedGeometry) return cachedGeometry;
  const binaryString = atob(INLAY_BASE_B64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  cachedGeometry = new Float32Array(bytes.buffer);
  return cachedGeometry;
}
